    "\u2066": "LRI", "\u2067": "RLI", "\u2068": "FSI", "\u2069": "PDI", "\u200B": "ZWSP",
    "\u200C": "ZWNJ", "\u200D": "ZWJ", "\uFEFF": "BOM"
